using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using DungeonGame.Quests;
using DungeonGame.Dialogue;
public static class VerifyGatheringQuestAssets
{
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Requires stopped Editor");var checks=new List<string>();var q=AssetDatabase.LoadAssetAtPath<QuestDefinition>("Assets/Quests/SuppliesForTheRoad/SuppliesForTheRoad.asset");if(q==null||!q.Validate(out _))throw new Exception("Invalid authored quest");checks.Add("Gathering quest definition validates");var conversation=AssetDatabase.LoadAssetAtPath<DialogueConversation>("Assets/Quests/SuppliesForTheRoad/NessaConversation.asset");if(conversation==null||conversation.Find(conversation.entryNode)==null||conversation.nodes.Any(n=>n.responses==null||n.responses.Any(r=>r==null)))throw new Exception("Invalid conversation");foreach(var n in conversation.nodes)foreach(var r in n.responses)if(!string.IsNullOrEmpty(r.nextNode)&&conversation.Find(r.nextNode)==null)throw new Exception("Missing conversation branch");checks.Add("Conversation branches and responses resolve");foreach(string path in new[]{"Assets/Prefabs/WorldInteract/Quartermaster_Nessa.prefab","Assets/Prefabs/Player/PlayerHolder.prefab"}){var root=PrefabUtility.LoadPrefabContents(path);try{if(root.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject))!=0)throw new Exception("Missing script: "+path);checks.Add("No missing scripts: "+path);var controller=root.GetComponentInChildren<QuestController>(true);if(controller!=null){if(!controller.quests.Contains(q)||!controller.quests.Any(x=>x.id=="below-the-trading-post"))throw new Exception("Player catalog lost an adventure");var service=new QuestService(controller.quests,null,()=>1,null);checks.Add("Existing player catalog retains both valid adventures");}else{var npc=root.GetComponentInChildren<DialogueNpc>(true);if(npc==null||npc.conversation!=conversation||root.GetComponentInChildren<Interactable>(true)==null)throw new Exception("NPC interaction missing");if(root.GetComponentsInChildren<UnityEngine.AI.NavMeshAgent>(true).Any(a=>a.enabled))throw new Exception("Stationary NPC requires disabled navigation on unbaked test floor");checks.Add("Nessa uses existing dialogue/interactable with stationary navigation");}}finally{PrefabUtility.UnloadPrefabContents(root);}}
 var scene=EditorSceneManager.OpenScene("Assets/Scenes/Test_Scenes/GatheringQuest_Test.unity",OpenSceneMode.Additive);try{var roots=scene.GetRootGameObjects();var nodes=roots.SelectMany(r=>r.GetComponentsInChildren<ResourceNode>(true)).ToArray();if(nodes.Length!=4||nodes.Any(n=>n.definition==null||!n.definition.IsValid))throw new Exception("Invalid resource test area");checks.Add("Saved fixture contains four valid nodes including two independent trees");var npc=roots.SelectMany(r=>r.GetComponentsInChildren<DialogueNpc>(true)).Single(n=>n.speakerName=="Quartermaster Nessa");var player=roots.SelectMany(r=>r.GetComponentsInChildren<QuestController>(true)).Single();if(!player.quests.Contains(q)||npc.conversation!=conversation)throw new Exception("Fixture quest wiring missing");checks.Add("Saved fixture binds the existing player catalog and Nessa conversation");}finally{EditorSceneManager.CloseScene(scene,true);}var report=new{passed=true,checks=checks.ToArray(),editScene=SceneManager.GetActiveScene().path,dirty=SceneManager.GetActiveScene().isDirty};System.IO.File.WriteAllText("Assets/Plan/Validation/gathering-quest-assets.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;}
}
